pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy an attacker contract that, when called, writes to slot 0 of the caller
        Attacker attacker = new Attacker();

        // Call forward with delegatecall semantics — in the bug, this modifies c's owner
        c.forward(address(attacker), abi.encodeWithSignature("attack()"));

        // In the reference (call), c.owner() remains original (this contract = address(this))
        // In the bug (delegatecall), c.owner() becomes address(attacker)
        // So we assert that it is NOT the attacker address (reference holds, bug breaks)
        assertTrue(c.owner() != address(attacker));
    }
}

contract Attacker {
    function attack() public {
        // Overwrites slot 0 of the caller's storage
        assembly {
            sstore(0, caller())
        }
    }
}

