pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Attacker {
    function setNumber(uint256) external {
        // This would modify the caller's storage if delegatecalled from C
        assembly {
            sstore(0, 42)
        }
    }
}

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker();
    }

    function testRegression_property() public {
        // Before the call, the owner (first slot) is the deployer of c
        address originalOwner = address(this);
        // Call forward with the attacker contract's address
        c.forward(address(attacker), abi.encodeWithSignature("setNumber(uint256)", 0));
        // For the reference (call), owner remains originalOwner
        // For the buggy (delegatecall), owner becomes address(attacker)
        assertTrue(c.owner() == originalOwner);
    }
}

