pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that selfdestructs when called
        address attacker = address(new Attacker());

        // Execute forward with the selfdestruct helper
        bytes memory data = abi.encodeWithSignature("kill()");
        c.forward(attacker, data);

        // The reference (call) leaves c alive, the bug (delegatecall) destroys c
        // Check that c still has code (reference passes, bug fails)
        uint256 codeSize;
        assembly { codeSize := extcodesize(c) }
        assertTrue(codeSize > 0);
    }
}

contract Attacker {
    function kill() external {
        selfdestruct(payable(address(0)));
    }
}

