    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Prepare calldata that self-calls and writes to storage slot 0 (owner)
        // The function selector for setOwner(address) is 0x893d20e8, but we just write directly
        bytes memory data = abi.encodeWithSignature("setOwner(address)", address(this));
        // Directly call forward with callee = address(c), which is itself
        // For delegatecall, this will modify the caller's storage (c's owner)
        c.forward(address(c), data);
        // Assert that owner was NOT changed by the reference (call) but WOULD be changed by bug (delegatecall)
        // In delegatecall, the inner setOwner would set owner to address(this) (test contract)
        // So after the call, owner should be msg.sender (test contract) for delegatecall
        // Since reference uses call, owner remains original deployer (address(this) = test contract)
        // Both end up same? Actually deployer is test contract too, so differentiate by checking if owner == address(c)
        // Simpler: deploy a helper contract that writes a different slot
        // Instead, we use a different approach: self-delegatecall can cause infinite loops, but for test we just check
        // Actually the reference call does nothing to c's storage, but delegatecall would execute setOwner on c
        // Since c has no setOwner function, call fails (requires success) but delegatecall would succeed and write
        // We need a contract with a setOwner function. Let's deploy such helper.
        Helper helper = new Helper();
        data = abi.encodeWithSignature("setOwner(address)", address(0xdead));
        c.forward(address(helper), data);
        // For delegatecall, this would write 0xdead to c's owner slot
        // For call, it writes to helper's owner slot
        // So after reference: c.owner() remains deployer (this contract)
        // After bug: c.owner() becomes 0xdead
        // We cannot read owner because it's private, but we can check address(c).balance or similar
        // Actually owner is private, but we can deploy a contract that exposes a read
        // Workaround: use a different state variable that is public
        // Given constraints, we must use public/external surface
        // Since C has no getter, we will use a try/catch on a revert to observe state
        // We'll check that a subsequent call behaves differently
        // For simplicity, let's read something else: after delegatecall, selfdestruct could be triggered
        // But given previous tries, we need a new approach
        // The only public surface of C is forward(). If delegatecall writes to slot 0, we can check by calling a function that reads slot 0
        // Since C has no such function, we must infer from behavior
        // Another idea: after delegatecall, attempt to call forward again with different data
        // Actually after delegatecall modifying owner, the constructor's owner check is irrelevant
        // Let's use a revert difference: if we cause a revert in delegatecall that consumes all gas?
        // I'll use a different concrete scenario: call a contract that does selfdestruct, and check address(c).balance after
        // But selfdestruct is deprecated
        // Finally, use the fact that the bug changes the owner to the callee's address
        // Since we cannot read owner, we can use the fact that the contract has no fallback => any call with non-existent function selector reverts
        // For delegatecall, if callee is a contract that has a fallback, the delegatecall executes fallback in context of c
        // This can change c's storage
        // Let's use a simple contract that writes to slot 0
        // Then check by calling a view function? None.
        // The only way is to check a revert: after delegatecall, the slot0 is corrupted; if we call forward with callee=address(0), it will revert differently
        // This is getting complex. I'll use the setOwner approach with a helper that has a public getter
        // But constraint: only interact through c, not helper
        // The helper's public getter is accessible via c? No
        // Abort: use the selfdestruct approach but ensure it's the only one not tried? Actually it's tried
        // Use the balance approach: deploy contract that selfdestructs to c, checking balance
        // Actually we need to store a value on c via delegatecall that affects a public getter
        // C has no public state, but address(c).balance is public
        // If delegatecall sends ether, balance changes
        // For reference call, balance unchanged; for delegatecall, balance could change if we selfdestruct to c
        // Simpler: let's use built-in address(this).balance
        // Create a contract that selfdestructs to c:
        HelperDestruct h = new HelperDestruct();
        vm.deal(address(h), 1 ether);
        uint256 balanceBefore = address(c).balance;
        // Call forward with h, data that triggers selfdestruct
        bytes memory selfdestructData = abi.encodeWithSignature("kill()");
        c.forward(address(h), selfdestructData);
        uint256 balanceAfter = address(c).balance; // Won't change because call executes in h's context
        // But delegatecall would execute kill in c's context, sending 1 ether to c? No, selfdestruct sends to beneficiary, not to c
        // Actually kill sends h's balance to address(c) via selfdestruct? Yes if we code it
        // Let's ensure we can detect difference with balance
        assertTrue(balanceAfter == balanceBefore + 1 ether); // reference: false, bug: true
    }
}

contract Helper {
    address public owner;
    function setOwner(address _owner) external { owner = _owner; }
}

contract HelperDestruct {
    function kill() external { selfdestruct(payable(msg.sender)); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);

        // Deploy an external contract that writes to slot 0 of the caller when called via delegatecall
        AttackerContract attackerContract = new AttackerContract();

        // The attacker calls forward with the attacker contract's address and data
        bytes memory data = abi.encodeWithSignature("attack()");
        vm.prank(attacker);
        c.forward(address(attackerContract), data);

        // After the call, in reference (call) owner should remain as msg.sender of constructor
        // In buggy (delegatecall), owner becomes attackerContract's address
        address expectedOwner = address(this); // msg.sender of constructor is the test contract
        address actualOwner = c.owner();
        assertTrue(actualOwner == expectedOwner, "Owner should not change after call");
    }
}

contract AttackerContract {
    function attack() public {
        // Write to slot 0 of the calling context
        assembly {
            sstore(0, caller())
        }
    }
}
